/* The declared return type of the method whose code this generator emits, or null. */
private Type declaredResult = null;

/*
 * The checker reads self, in a trait whose comprises clause lists types
 * and in a trait with a self-type parameter, as also a value of those
 * types (traits.tex, section "Trait Declarations"), so self, or a value
 * that has its type, may stand where such a type is declared.  The JVM's
 * verifier knows only the trait's interface, so the value on the stack is
 * cast where the declared type is a strict subtype of the trait.  A trait
 * that lists a type at a where-clause variable gets no cast: there the
 * checker's type names a variable of its own, which no class has.
 */
private void castToTypeBelow(Expr expr, Type declared) {
    if (!(declared instanceof TraitType || declared instanceof VarType)) return;
    Option<Type> ot = expr.getInfo().getExprType();
    if (ot.isNone()) return;
    Type t = ot.unwrap();
    if (t instanceof com.sun.fortress.nodes.UnionType) {
        // A typecase has the union of its arms' types: self's type where each arm has it.
        Type one = null;
        for (Type e : ((com.sun.fortress.nodes.UnionType) t).getElements()) {
            if (e instanceof BottomType) continue;
            if (one != null && !one.equals(e)) return;
            one = e;
        }
        t = one;
    }
    if (!(t instanceof TraitSelfType)) return;
    TraitSelfType self_t = (TraitSelfType) t;
    Type apparent = self_t.getNamed();
    if (self_t.getComprised().isEmpty() || !(apparent instanceof TraitType)) return;
    if (typeAnalyzer.opensSizes(apparent)) return;
    if (typeAnalyzer.lteq(apparent, declared) || !typeAnalyzer.lteq(declared, apparent)) return;
    String cast_to = NamingCzar.jvmTypeDesc(declared, thisApi(), false, true);
    InstantiatingClassloader.generalizedCastTo(mv, cast_to);
}

private void conditionallyCastParameter(Expr expr, Type domain_type) {
    conditionallyCastParameter(expr == null ?
            Null.<Type>make() : expr.getInfo().getExprType(),
            domain_type);
}
    /**
 * @param domain_type
 */
private void conditionallyCastParameter(Option<Type> apparent_type, Type domain_type) {
    if (domain_type instanceof ArrowType) {
        // insert cast
        String cast_to = NamingCzar.jvmTypeDesc(domain_type, thisApi(), false, true);
        InstantiatingClassloader.generalizedCastTo(mv, cast_to);
    } else if ((domain_type instanceof TupleType) && ((TupleType)domain_type).getElements().size() > 0) {
        // insert cast
        String cast_to = NamingCzar.jvmTypeDesc(domain_type, thisApi(), false, true);
        InstantiatingClassloader.generalizedCastTo(mv, cast_to);
    } else if ((domain_type instanceof VarType) &&
            ((VarType)domain_type).getName().getText().equals(Naming.UP_INDEX)) {
        // insert cast
        String cast_to = NamingCzar.jvmTypeDesc(domain_type, thisApi(), false, true);
        InstantiatingClassloader.generalizedCastTo(mv, cast_to);
    } else if (apparent_type.isNone() ||
            /* This will insert unnecessary casts, but the JIT should remove them
             * It might be worthwhile to do a simple walk of supertraits of the
             * apparent_type to see if the subtyping is a trivial instance of
             * will-work-in-Java.
             */
            0 != NodeComparator.compare(apparent_type.unwrap(), domain_type)) {
        String cast_to = NamingCzar.jvmTypeDesc(domain_type, thisApi(), false, true);
        InstantiatingClassloader.generalizedCastTo(mv, cast_to);
    }
}

private void generateHigherOrderCall(Type t) {
    if (!(t instanceof ArrowType)) {
        throw sayWhat(t,"Higher-order call to non-arrow type " + t);
    }
    ArrowType at = (ArrowType)t;
    String desc = NamingCzar.makeArrowDescriptor(at, thisApi());
    String sig = NamingCzar.jvmSignatureFor(at,thisApi());
    // System.err.println(desc+".apply"+sig+" call");
    mv.visitMethodInsn(INVOKEINTERFACE, desc,
                       Naming.APPLY_METHOD, sig);
}

