public void forTypecase(Typecase x) {
    Expr expr = x.getBindExpr();
    expr.accept(this);

    Label done = new Label();
    for (TypecaseClause c : x.getClauses()) {
        Label next = new Label();
        Label end = new Label();
        TypeOrPattern match = c.getMatchType();
        Type typ = getType(match);
        mv.visitInsn(DUP);
        InstantiatingClassloader.generalizedInstanceOf(mv, NamingCzar.jvmBoxedTypeName(typ, thisApi()));
        mv.visitJumpInsn(IFNE, next);
        mv.visitJumpInsn(GOTO, end);
        mv.visitLabel(next);
        if (c.getName().isSome()) {
            bindAndGenerateClauseBody(c.getName().unwrap(), typ, c.getBody());
        } else {
            mv.visitInsn(POP);
            c.getBody().accept(this);
        }
        mv.visitJumpInsn(GOTO, done);
        mv.visitLabel(end);
     }

    if (x.getElseClause().isSome()) {
        mv.visitInsn(POP);
    	x.getElseClause().unwrap().accept(this);
        mv.visitJumpInsn(GOTO, done);
    }

     mv.visitMethodInsn(INVOKESTATIC,
                        NamingCzar.internalFortressVoid, NamingCzar.make,
                        NamingCzar.voidToFortressVoid);

     mv.visitLabel(done);


}

private void bindAndGenerateClauseBody(Id name, Type typ, Block body) {
    InstantiatingClassloader.generalizedCastTo(mv, NamingCzar.jvmBoxedTypeName(typ, thisApi()));
    CodeGen cg = new CodeGen(this);
    VarCodeGen vcg = new VarCodeGen.LocalVar(name, typ, cg);
    cg.addLocalVar(vcg);
    vcg.assignValue(mv);
    body.accept(cg);
    vcg.outOfScope(mv);
}


